9	import SwiftUI
10	import SwiftData
11	
12	struct ProfileView: View {
13	    @Environment(\.modelContext) private var context
14	    @Environment(\.exerciseCatalog) private var catalog
15	    @Query private var profiles: [UserProfile]
16	    @Query private var settingsList: [AppSettings]
17	    @Query private var plans: [Plan]
18	    @Query private var history: [HistoryEntry]
19	    @State private var showResetConfirm = false
20	    @State private var selectedStat: StatKind?
21	
22	    private var profile: UserProfile { profiles.first ?? context.userProfile() }
23	    private var settings: AppSettings { settingsList.first ?? context.appSettings() }
24	    private var scheduledDays: Set<Weekday> { StreakEngine.scheduledDays(in: plans) }
25	    private var plansWithReports: [Plan] { plans.filter(\.hasReport) }
26	    private var workoutStreak: Int {
27	        StreakEngine.workoutStreak(scheduledDays: scheduledDays, doneDates: profile.doneDates)
28	    }
29	    private var weekStreak: Int {
30	        StreakEngine.weekStreak(scheduledDays: scheduledDays, doneDates: profile.doneDates)
31	    }
32	
33	    var body: some View {
34	        NavigationStack {
35	            ScrollView {
36	                VStack(alignment: .leading, spacing: 18) {
37	                    Text("Profile").font(.screenTitle).foregroundStyle(Color.textPrimary)
38	                    profileHeader
39	                    statsRow
40	                    if !plansWithReports.isEmpty { coachReports }
41	                    preferences
42	                    resetButton
43	                }
44	                .padding(20)
45	            }
46	            .scrollDismissesKeyboard(.immediately)
47	            .hideKeyboardOnTap()
48	            .background(Color.bg.ignoresSafeArea())
49	            .toolbar(.hidden, for: .navigationBar)
50	            .confirmationDialog("Reset all data?", isPresented: $showResetConfirm, titleVisibility: .visible) {
51	                Button("Reset everything", role: .destructive) { resetAll() }
52	                Button("Cancel", role: .cancel) {}
53	            } message: {
54	                Text("This deletes all plans, history, and settings, and restarts onboarding.")
55	            }
56	            .sheet(item: $selectedStat) { kind in
57	                StatDetailSheet(kind: kind, doneDates: profile.doneDates, history: history,
58	                                catalog: catalog, scheduledCount: scheduledDays.count,
59	                                workoutStreakValue: workoutStreak, weekStreakValue: weekStreak,
60	                                totalWorkouts: profile.totalWorkouts)
61	            }
62	        }
63	    }
64	
65	    private var profileHeader: some View {
66	        HStack(spacing: 14) {
67	            Text(profile.initial)
68	                .font(.rounded(24, .black)).foregroundStyle(.white)
69	                .frame(width: 60, height: 60)
70	                .background(Circle().fill(LinearGradient(colors: [Color.accent, Color.accentPress],
71	                                                         startPoint: .topLeading, endPoint: .bottomTrailing)))
72	            VStack(alignment: .leading, spacing: 3) {
73	                Text(profile.name).font(.rounded(20, .black)).foregroundStyle(Color.textPrimary)
