85	            stat("\(workoutStreak)", "Workout streak") { selectedStat = .workoutStreak }
86	            stat("\(weekStreak)", "Week streak") { selectedStat = .weekStreak }
87	        }
88	    }
89	
90	    private var coachReports: some View {
91	        VStack(alignment: .leading, spacing: 12) {
