//
//  ProfileView.swift
//  Replog
//
//  Avatar + goal, lifetime stats, and preferences (units, dark mode, rest timer),
//  plus a reset.
//

import SwiftUI
import SwiftData

struct ProfileView: View {
    @Environment(\.modelContext) private var context
    @Environment(\.exerciseCatalog) private var catalog
    @Query private var profiles: [UserProfile]
    @Query private var settingsList: [AppSettings]
    @Query private var plans: [Plan]
    @Query private var history: [HistoryEntry]
    @State private var showResetConfirm = false
    @State private var selectedStat: StatKind?

    private var profile: UserProfile { profiles.first ?? context.userProfile() }
    private var settings: AppSettings { settingsList.first ?? context.appSettings() }
    private var scheduledDays: Set<Weekday> { StreakEngine.scheduledDays(in: plans) }
    private var plansWithReports: [Plan] { plans.filter(\.hasReport) }
    private var workoutStreak: Int {
        StreakEngine.workoutStreak(scheduledDays: scheduledDays, doneDates: profile.doneDates)
    }
    private var weekStreak: Int {
        StreakEngine.weekStreak(scheduledDays: scheduledDays, doneDates: profile.doneDates)
    }

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 18) {
                    Text("Profile").font(.screenTitle).foregroundStyle(Color.textPrimary)
                    profileHeader
                    statsRow
                    if !plansWithReports.isEmpty { coachReports }
                    preferences
                    resetButton
                }
                .padding(20)
            }
            .scrollDismissesKeyboard(.immediately)
            .hideKeyboardOnTap()
            .background(Color.bg.ignoresSafeArea())
            .toolbar(.hidden, for: .navigationBar)
            .confirmationDialog("Reset all data?", isPresented: $showResetConfirm, titleVisibility: .visible) {
                Button("Reset everything", role: .destructive) { resetAll() }
                Button("Cancel", role: .cancel) {}
            } message: {
                Text("This deletes all plans, history, and settings, and restarts onboarding.")
            }
            .sheet(item: $selectedStat) { kind in
                StatDetailSheet(kind: kind, doneDates: profile.doneDates, history: history,
                                catalog: catalog, scheduledCount: scheduledDays.count,
                                workoutStreakValue: workoutStreak, weekStreakValue: weekStreak,
                                totalWorkouts: profile.totalWorkouts)
            }
        }
    }

    private var profileHeader: some View {
        HStack(spacing: 14) {
            Text(profile.initial)
                .font(.rounded(24, .black)).foregroundStyle(.white)
                .frame(width: 60, height: 60)
                .background(Circle().fill(LinearGradient(colors: [Color.accent, Color.accentPress],
                                                         startPoint: .topLeading, endPoint: .bottomTrailing)))
            VStack(alignment: .leading, spacing: 3) {
                Text(profile.name).font(.rounded(20, .black)).foregroundStyle(Color.textPrimary)
                Text(profile.goal.displayName).font(.rounded(13, .bold)).foregroundStyle(Color.accent)
            }
            Spacer()
        }
        .padding(16)
        .cardSurface()
    }

    private var statsRow: some View {
        HStack(spacing: 12) {
            stat("\(profile.totalWorkouts)", "Workouts") { selectedStat = .workouts }
            stat("\(workoutStreak)", "Workout streak") { selectedStat = .workoutStreak }
            stat("\(weekStreak)", "Week streak") { selectedStat = .weekStreak }
        }
    }

    private var coachReports: some View {
        VStack(alignment: .leading, spacing: 12) {
            SectionHeader(title: "AI Coach Reports")
            VStack(spacing: 0) {
                ForEach(Array(plansWithReports.enumerated()), id: \.element.id) { index, plan in
                    NavigationLink {
                        CoachReportView(title: plan.headline.isEmpty ? plan.name : plan.headline,
                                        markdown: plan.reportMarkdown)
                    } label: {
                        HStack(spacing: 12) {
                            icon("sparkles")
                            VStack(alignment: .leading, spacing: 2) {
                                Text(plan.name).font(.rounded(15, .heavy)).foregroundStyle(Color.textPrimary)
                                Text("The science behind your plan")
                                    .font(.rounded(12, .semibold)).foregroundStyle(Color.text2)
                            }
                            Spacer()
                            Image(systemName: "chevron.right").font(.system(size: 13, weight: .bold))
                                .foregroundStyle(Color.text3)
                        }
                        .padding(14)
                    }
                    .buttonStyle(.plain)
                    if index < plansWithReports.count - 1 { Divider().padding(.leading, 56) }
                }
            }
            .cardSurface()
        }
    }

    private func stat(_ value: String, _ label: String, action: @escaping () -> Void) -> some View {
        Button(action: action) {
            VStack(spacing: 2) {
                Text(value).font(.metric).foregroundStyle(Color.textPrimary).tabularNumbers()
                Text(label).font(.rounded(12, .bold)).foregroundStyle(Color.text2)
            }
            .frame(maxWidth: .infinity).padding(.vertical, 16).cardSurface()
        }
        .buttonStyle(.plain)
    }

    private var preferences: some View {
        VStack(alignment: .leading, spacing: 12) {
            SectionHeader(title: "Preferences")
            VStack(spacing: 0) {
                restDurationRow
                Divider().padding(.leading, 14)
                toggleRow(icon: "timer", title: "Rest timer auto-start",
                          isOn: Binding(get: { settings.restTimerAuto },
                                        set: { settings.restTimerAuto = $0; save() }))
                Divider().padding(.leading, 14)
                unitsRow
                Divider().padding(.leading, 14)
                toggleRow(icon: "moon.fill", title: "Dark mode",
                          isOn: Binding(get: { settings.darkMode },
                                        set: { settings.darkMode = $0; save() }))
            }
            .cardSurface()
        }
    }

    /// The app-wide default rest between sets (per-exercise overrides win in a workout).
    private var restDurationRow: some View {
        HStack(spacing: 12) {
            icon("clock.arrow.circlepath")
            Text("Rest duration").font(.rounded(15, .heavy)).foregroundStyle(Color.textPrimary)
            Spacer()
            NumericStepperField(display: "\(settings.restSeconds)", keyboard: .numberPad,
                                onMinus: { settings.restSeconds = max(5, settings.restSeconds - 15); save() },
                                onPlus: { settings.restSeconds = min(600, settings.restSeconds + 15); save() },
                                onCommit: {
                                    if let v = Int($0.filter(\.isNumber)) {
                                        settings.restSeconds = min(600, max(5, v)); save()
                                    }
                                })
            Text("sec").font(.rounded(11, .bold)).foregroundStyle(Color.text3)
        }
        .padding(14)
    }

    private var unitsRow: some View {
        HStack(spacing: 12) {
            icon("scalemass.fill")
            Text("Units").font(.rounded(15, .heavy)).foregroundStyle(Color.textPrimary)
            Spacer()
            SegmentedToggle(options: [(Units.kg, "kg"), (Units.lb, "lb")],
                            selection: Binding(get: { settings.units },
                                               set: { settings.units = $0; save() }))
                .frame(width: 120)
        }
        .padding(14)
    }

    private func toggleRow(icon iconName: String, title: String, isOn: Binding<Bool>) -> some View {
        HStack(spacing: 12) {
            icon(iconName)
            Text(title).font(.rounded(15, .heavy)).foregroundStyle(Color.textPrimary)
            Spacer()
            Toggle("", isOn: isOn).labelsHidden().tint(.accent)
        }
        .padding(14)
    }

    private func icon(_ name: String) -> some View {
        Image(systemName: name).font(.system(size: 14, weight: .bold)).foregroundStyle(Color.accent)
            .frame(width: 30, height: 30)
            .background(RoundedRectangle(cornerRadius: 9, style: .continuous).fill(Color.accentSoft))
    }

    private var resetButton: some View {
        Button(role: .destructive) { showResetConfirm = true } label: {
            HStack(spacing: 6) { Image(systemName: "arrow.counterclockwise"); Text("Reset all data") }
                .font(.rounded(15, .heavy)).foregroundStyle(Color.down)
                .frame(maxWidth: .infinity).padding(.vertical, 14)
                .background(RoundedRectangle(cornerRadius: 14, style: .continuous).fill(Color.down.opacity(0.12)))
        }
        .buttonStyle(.plain)
    }

    private func save() { try? context.save() }

    private func resetAll() {
        for plan in plans { context.delete(plan) }
        for entry in history { context.delete(entry) }
        let sessions = (try? context.fetch(FetchDescriptor<ActiveSession>())) ?? []
        for session in sessions { context.delete(session) }
        profile.onboardingDone = false
        profile.name = ""
        profile.streak = 0
        profile.weekStreak = 0
        profile.totalWorkouts = 0
        profile.doneDates = []
        try? context.save()
    }
}

//
//  ReplogStore.swift
//  Replog
//
//  Central SwiftData schema, container factories, and fetch-or-create singletons
//  for UserProfile / AppSettings.
//

import Foundation
import SwiftData

enum ReplogSchema {
    /// All persisted model types.
    static let models: [any PersistentModel.Type] = [
        Plan.self, Workout.self, PlanItem.self, SetTemplate.self,
        ActiveSession.self, SessionExercise.self, LoggedSet.self,
        HistoryEntry.self, UserProfile.self, AppSettings.self,
        CoachingLog.self, BodyweightEntry.self
    ]

    /// The app's on-disk container.
    /// On a fresh device install `Library/Application Support` may not exist yet, which
    /// makes SwiftData fail to create its store ("Failed to create file; code = 2"). We
    /// create that directory first, then open the store; if the store itself is corrupt
    /// or schema-incompatible (e.g. left over from an older build), we wipe it once and
    /// retry, falling back to in-memory as a last resort so the app always launches.
    @MainActor
    static func container() -> ModelContainer {
        let schema = Schema(models)
        let config = ModelConfiguration(isStoredInMemoryOnly: false)
        let storeURL = config.url

        // Ensure the store's parent directory exists.
        try? FileManager.default.createDirectory(
            at: storeURL.deletingLastPathComponent(),
            withIntermediateDirectories: true
        )

        if let c = try? ModelContainer(for: schema, configurations: config) { return c }

        // Genuine corruption / incompatible schema: remove the store files and retry once.
        for suffix in ["", "-shm", "-wal"] {
            try? FileManager.default.removeItem(at: URL(fileURLWithPath: storeURL.path + suffix))
        }
        if let recovered = try? ModelContainer(for: schema, configurations: config) { return recovered }

        // Last resort so the UI still runs (data won't persist).
        return try! ModelContainer(for: schema, configurations: ModelConfiguration(isStoredInMemoryOnly: true))
    }

    /// An ephemeral container for tests and SwiftUI previews.
    @MainActor
    static func inMemoryContainer() -> ModelContainer {
        let config = ModelConfiguration(isStoredInMemoryOnly: true)
        // Force-try is acceptable here: an in-memory store cannot fail for schema reasons
        // that wouldn't also fail the on-disk store caught at app launch.
        return try! ModelContainer(for: Schema(models), configurations: config)
    }
}

// MARK: - Singleton fetch-or-create

extension ModelContext {
    /// Returns the single UserProfile, creating it on first access.
    func userProfile() -> UserProfile {
        if let existing = (try? fetch(FetchDescriptor<UserProfile>()))?.first {
            return existing
        }
        let profile = UserProfile()
        insert(profile)
        return profile
    }

    /// Returns the single AppSettings row, creating it on first access.
    func appSettings() -> AppSettings {
        if let existing = (try? fetch(FetchDescriptor<AppSettings>()))?.first {
            return existing
        }
        let settings = AppSettings()
        insert(settings)
        return settings
    }

    /// All plans in display order.
    func allPlans() -> [Plan] {
        let descriptor = FetchDescriptor<Plan>(sortBy: [SortDescriptor(\.order)])
        return (try? fetch(descriptor)) ?? []
    }

    /// Recomputes both streaks on `profile` from the current plan schedule + completed days.
    /// Call after finishing a workout or whenever the schedule changes.
    func recomputeStreaks(profile: UserProfile, today: Date = Date()) {
        let scheduled = StreakEngine.scheduledDays(in: allPlans())
        profile.streak = StreakEngine.workoutStreak(
            scheduledDays: scheduled, doneDates: profile.doneDates, today: today)
        profile.weekStreak = StreakEngine.weekStreak(
            scheduledDays: scheduled, doneDates: profile.doneDates, today: today)
    }

    /// History entries for one exercise, oldest first.
    func history(forExercise exId: String) -> [HistoryEntry] {
        let descriptor = FetchDescriptor<HistoryEntry>(
            predicate: #Predicate { $0.exId == exId },
            sortBy: [SortDescriptor(\.date)]
        )
        return (try? fetch(descriptor)) ?? []
    }

    // MARK: - Bodyweight

    /// All bodyweight check-ins, oldest first (matches `history(forExercise:)`).
    func bodyweightEntries() -> [BodyweightEntry] {
        let descriptor = FetchDescriptor<BodyweightEntry>(sortBy: [SortDescriptor(\.date)])
        return (try? fetch(descriptor)) ?? []
    }

    /// The most recent bodyweight check-in, if any.
    func latestBodyweight() -> BodyweightEntry? {
        var descriptor = FetchDescriptor<BodyweightEntry>(
            sortBy: [SortDescriptor(\.date, order: .reverse)])
        descriptor.fetchLimit = 1
        return ((try? fetch(descriptor)) ?? []).first
    }

    /// Records a bodyweight check-in. One entry per calendar day: logging again on the
    /// same day updates that day's entry instead of inserting a duplicate.
    @discardableResult
    func logBodyweight(_ weightKg: Double, date: Date = Date()) -> BodyweightEntry {
        if let sameDay = bodyweightEntries().last(where: {
            Calendar.current.isDate($0.date, inSameDayAs: date)
        }) {
            sameDay.weightKg = weightKg
            sameDay.date = date
            return sameDay
        }
        let entry = BodyweightEntry(weightKg: weightKg, date: date)
        insert(entry)
        return entry
    }

    // MARK: - Coaching memory

    /// Records a coaching note into the durable memory and returns the inserted log.
    /// This is the single write path the trainer uses to "remember" something.
    @discardableResult
    func recordCoaching(
        _ kind: CoachingKind,
        summary: String,
        date: Date = Date(),
        exId: String? = nil,
        planId: UUID? = nil,
        payload: CoachingPayload = CoachingPayload()
    ) -> CoachingLog {
        let log = CoachingLog(
            kind: kind, summary: summary, date: date,
            exId: exId, planId: planId, payload: payload
        )
        insert(log)
        return log
    }

    /// Coaching logs, newest first. Optionally filtered to one `kind` and capped to `limit`.
    func coachingLogs(kind: CoachingKind? = nil, limit: Int? = nil) -> [CoachingLog] {
        var descriptor = FetchDescriptor<CoachingLog>(sortBy: [SortDescriptor(\.date, order: .reverse)])
        if let kind {
            let raw = kind.rawValue
            descriptor.predicate = #Predicate { $0.kindRaw == raw }
        }
        if let limit { descriptor.fetchLimit = limit }
        return (try? fetch(descriptor)) ?? []
    }

    /// The most recent coaching log of a given kind, if any.
    func latestCoachingLog(kind: CoachingKind) -> CoachingLog? {
        coachingLogs(kind: kind, limit: 1).first
    }

    /// Coaching logs concerning one exercise, newest first.
    func coachingLogs(forExercise exId: String) -> [CoachingLog] {
        let descriptor = FetchDescriptor<CoachingLog>(
            predicate: #Predicate { $0.exId == exId },
            sortBy: [SortDescriptor(\.date, order: .reverse)]
        )
        return (try? fetch(descriptor)) ?? []
    }
}

//
//  StreakEngine.swift
//  Replog
//
//  Schedule-aware streaks. Unlike a Duolingo daily streak, these are driven by the
//  user's *plan schedule* (which weekdays have a workout):
//
//   • Workout streak — consecutive scheduled workouts completed. A scheduled weekday
//     that ends without its workout done resets it to 0. Today's scheduled workout,
//     while still undone, does not break it (in-progress grace).
//
//   • Week streak — consecutive "perfect weeks" (every scheduled workout that week
//     completed). Because a missed workout breaks the workout streak, it also breaks
//     the week streak ("grouped inside"): the workout streak counts sessions, the week
//     streak counts whole weeks, and a single miss resets both.
//
//  All functions are pure (no SwiftData), so they're fully unit-testable.
//

import Foundation

enum StreakEngine {

    /// Distinct weekdays that have at least one scheduled workout across the given plans.
    static func scheduledDays(in plans: [Plan]) -> Set<Weekday> {
        Set(plans.flatMap(\.workouts).map(\.day))
    }

    /// Consecutive scheduled workouts completed, counting back from `today`.
    /// Stops at the first *past* scheduled weekday with no completion. A scheduled
    /// workout that is still due today (undone) is skipped, not counted as a miss.
    static func workoutStreak(
        scheduledDays: Set<Weekday>,
        doneDates: [Date],
        today: Date = Date(),
        calendar: Calendar = .current
    ) -> Int {
        guard !scheduledDays.isEmpty else { return 0 }
        let doneDays = Set(doneDates.map { calendar.startOfDay(for: $0) })
        guard !doneDays.isEmpty else { return 0 }

        let startOfToday = calendar.startOfDay(for: today)
        var cursor = startOfToday
        var count = 0
        // Safety bound: never walk more than ~2 years of days.
        for _ in 0..<732 {
            let weekday = Weekday.from(cursor, calendar: calendar)
            if scheduledDays.contains(weekday) {
                if doneDays.contains(cursor) {
                    count += 1
                } else if cursor != startOfToday {
                    // A past scheduled workout was missed → streak ends here.
                    break
                }
                // else: today's scheduled workout is still due — grace, don't break.
            }
            guard let prev = calendar.date(byAdding: .day, value: -1, to: cursor) else { break }
            cursor = prev
            // Once we're older than every completion, the next scheduled day is a miss.
            if let earliest = doneDays.min(), cursor < earliest { break }
        }
        return count
    }

    /// Consecutive "perfect weeks" ending at the current week.
    ///
    /// • The current week counts as in-progress (+1) when every *elapsed* scheduled
    ///   workout (on or before today) is done and at least one has been done. If an
    ///   elapsed scheduled workout this week was missed, the whole streak is broken (0).
    /// • Each prior week counts only if *all* of its scheduled workouts were completed.
    static func weekStreak(
        scheduledDays: Set<Weekday>,
        doneDates: [Date],
        today: Date = Date(),
        calendar: Calendar = .current
    ) -> Int {
        guard !scheduledDays.isEmpty else { return 0 }
        let doneDays = Set(doneDates.map { calendar.startOfDay(for: $0) })
        let startOfToday = calendar.startOfDay(for: today)
        guard let thisWeekStart = startOfWeek(for: startOfToday, calendar: calendar) else { return 0 }

        var weeks = 0

        // Current (in-progress) week.
        let scheduledThisWeek = scheduledDates(weekStart: thisWeekStart, scheduledDays: scheduledDays, calendar: calendar)
        // A *past* scheduled workout (before today) left undone is a miss → breaks both streaks.
        // Today's scheduled workout, while still due, gets the same grace as the workout streak.
        let pastScheduled = scheduledThisWeek.filter { $0 < startOfToday }
        if pastScheduled.contains(where: { !doneDays.contains($0) }) {
            return 0
        }
        let doneThisWeek = scheduledThisWeek.filter { $0 <= startOfToday && doneDays.contains($0) }
        if !doneThisWeek.isEmpty {
            weeks += 1 // On track with at least one scheduled workout done.
        }

        // Prior weeks: require every scheduled workout completed.
        guard var cursor = calendar.date(byAdding: .day, value: -7, to: thisWeekStart) else { return weeks }
        for _ in 0..<104 { // ~2 years of weeks
            let scheduled = scheduledDates(weekStart: cursor, scheduledDays: scheduledDays, calendar: calendar)
            guard !scheduled.isEmpty, scheduled.allSatisfy({ doneDays.contains($0) }) else { break }
            weeks += 1
            guard let prev = calendar.date(byAdding: .day, value: -7, to: cursor) else { break }
            cursor = prev
        }
        return weeks
    }

    // MARK: - Helpers

    /// The Sunday that starts the week containing `date` (matches the Today week strip).
    static func startOfWeek(for date: Date, calendar: Calendar = .current) -> Date? {
        let startOfDay = calendar.startOfDay(for: date)
        let weekdayIndex = calendar.component(.weekday, from: startOfDay) - 1 // 0 = Sunday
        return calendar.date(byAdding: .day, value: -weekdayIndex, to: startOfDay)
    }

    /// The concrete dates of the scheduled weekdays within the week starting `weekStart`.
    private static func scheduledDates(
        weekStart: Date,
        scheduledDays: Set<Weekday>,
        calendar: Calendar
    ) -> [Date] {
        (0..<7).compactMap { offset -> Date? in
            guard let date = calendar.date(byAdding: .day, value: offset, to: weekStart) else { return nil }
            return scheduledDays.contains(Weekday.from(date, calendar: calendar)) ? date : nil
        }
    }
}

//
//  BodyweightTracker.swift
//  Replog
//
//  Pure logic for the periodic bodyweight check-in: when the next check-in is due,
//  and the trend over the recent series (delta, weekly rate, direction). Storage is
//  `BodyweightEntry`; display conversion lives in `Formulas`.
//

import Foundation

/// A digest of the recent bodyweight series, ready for the Today card.
struct BodyweightSnapshot: Equatable, Sendable {
    /// The latest logged weight, in kg.
    var currentKg: Double
    /// When it was logged.
    var date: Date
    /// Change vs the previous check-in, in kg (nil for the first entry).
    var deltaKg: Double?
    /// Least-squares rate of change over the trailing window, in kg per week
    /// (nil until two check-ins land inside the window).
    var weeklyRateKg: Double?
    /// Direction of `weeklyRateKg` with a noise deadband (`.none` while rate is nil).
    var direction: Trend
    /// The recent series (oldest first) scaled for `Sparkline`'s integer values.
    var sparklineValues: [Int]
}

enum BodyweightTracker {

    /// Days between check-in prompts.
    static let checkInIntervalDays = 7
    /// Trailing window the weekly rate is fitted over.
    static let trendWindowDays = 28
    /// |rate| below this reads as scale noise, not a trend (kg per week).
    static let flatBandKgPerWeek = 0.15
    /// How many recent entries the sparkline shows.
    static let sparklinePoints = 12

    /// Whether the periodic check-in is due: no entry yet, or the last one is at least
    /// `checkInIntervalDays` calendar days old.
    static func checkInDue(lastDate: Date?, now: Date = Date(),
                           calendar: Calendar = .current) -> Bool {
        guard let lastDate else { return true }
        let from = calendar.startOfDay(for: lastDate)
        let to = calendar.startOfDay(for: now)
        let days = calendar.dateComponents([.day], from: from, to: to).day ?? 0
        return days >= checkInIntervalDays
    }

    /// Digests the series into the Today-card snapshot. Order-invariant; nil when empty.
    @MainActor
    static func snapshot(entries: [BodyweightEntry]) -> BodyweightSnapshot? {
        let sorted = entries.sorted { $0.date < $1.date }
        guard let latest = sorted.last else { return nil }

        let previous = sorted.dropLast().last
        let rate = weeklyRate(sorted: sorted, anchoredAt: latest.date)

        return BodyweightSnapshot(
            currentKg: latest.weightKg,
            date: latest.date,
            deltaKg: previous.map { latest.weightKg - $0.weightKg },
            weeklyRateKg: rate,
            direction: direction(weeklyRateKg: rate),
            // 0.1 kg resolution — Sparkline normalises, so only relative shape matters.
            sparklineValues: sorted.suffix(sparklinePoints).map { Int(($0.weightKg * 10).rounded()) }
        )
    }

    /// Whether a trend direction moves toward (`true`), against (`false`), or neutrally
    /// (nil) with respect to the user's goal. Drives the card tint only — flat is always
    /// neutral, and recomp/sport have no "right" direction for the scale.
    static func isFavorable(_ direction: Trend, for goal: Goal) -> Bool? {
        switch (direction, goal) {
        case (.up, .buildMuscle): return true
        case (.up, .loseWeight): return false
        case (.down, .loseWeight): return true
        case (.down, .buildMuscle): return false
        default: return nil
        }
    }

    // MARK: - Internals

    /// Least-squares slope (kg/week) over entries within `trendWindowDays` of the anchor.
    @MainActor
    private static func weeklyRate(sorted: [BodyweightEntry], anchoredAt anchor: Date) -> Double? {
        let windowStart = anchor.addingTimeInterval(-Double(trendWindowDays) * 86_400)
        let window = sorted.filter { $0.date >= windowStart }
        guard window.count >= 2 else { return nil }

        let days = window.map { $0.date.timeIntervalSince(windowStart) / 86_400 }
        let weights = window.map(\.weightKg)
        let n = Double(window.count)
        let meanX = days.reduce(0.0, +) / n
        let meanY = weights.reduce(0.0, +) / n
        var covXY = 0.0
        var varX = 0.0
        for (x, y) in zip(days, weights) {
            covXY += (x - meanX) * (y - meanY)
            varX += (x - meanX) * (x - meanX)
        }
        // All entries on the same day (upsert makes this rare): no time spread, no rate.
        guard varX > 0 else { return nil }
        return covXY / varX * 7
    }

    private static func direction(weeklyRateKg: Double?) -> Trend {
        guard let rate = weeklyRateKg else { return .none }
        if rate > flatBandKgPerWeek { return .up }
        if rate < -flatBandKgPerWeek { return .down }
        return .flat
    }
}

