//
//  Profile.swift
//  Replog
//
//  Single-row user profile & app settings. Stored in SwiftData and fetched-or-created
//  via the helpers in ModelContainer+Replog.
//

import Foundation
import SwiftData

/// The user's training goal from onboarding.
enum Goal: String, Codable, CaseIterable, Identifiable, Sendable {
    case buildMuscle, loseWeight, recomp, sport
    var id: String { rawValue }
    var displayName: String {
        switch self {
        case .buildMuscle: return "Build muscle"
        case .loseWeight:  return "Lose weight"
        case .recomp:      return "Build muscle & lose fat"
        case .sport:       return "Train for a sport"
        }
    }
    /// Short label for chips / the Profile header.
    var shortName: String {
        switch self {
        case .buildMuscle: return "Hypertrophy"
        case .loseWeight:  return "Fat loss"
        case .recomp:      return "Recomposition"
        case .sport:       return "Sport"
        }
    }
}

/// Display unit for weights. Storage is always kg.
enum Units: String, Codable, CaseIterable, Identifiable, Sendable {
    case kg, lb
    var id: String { rawValue }
    var label: String { rawValue }
}

@Model
final class UserProfile {
    /// The user's full name ("First Last"), captured during onboarding.
    var name: String = ""
    var goalRaw: String = Goal.buildMuscle.rawValue
    /// Consecutive scheduled workouts completed (see `StreakEngine.workoutStreak`).
    var streak: Int = 0
    /// Consecutive "perfect weeks" (see `StreakEngine.weekStreak`).
    var weekStreak: Int = 0
    var doneDates: [Date] = []
    var onboardingDone: Bool = false
    var totalWorkouts: Int = 0

    init(name: String = "", goal: Goal = .buildMuscle) {
        self.name = name
        self.goalRaw = goal.rawValue
    }

    var goal: Goal {
        get { Goal(rawValue: goalRaw) ?? .buildMuscle }
        set { goalRaw = newValue.rawValue }
    }

    /// The consecutive-workout streak (alias for `streak`, for readable call sites).
    var workoutStreak: Int {
        get { streak }
        set { streak = newValue }
    }

    /// First name for greetings, falling back to a friendly default.
    var firstName: String {
        let first = name.split(separator: " ").first.map(String.init) ?? name
        return first.isEmpty ? "there" : first
    }

    /// The user's initial for the avatar.
    var initial: String {
        let trimmed = name.trimmingCharacters(in: .whitespaces)
        return trimmed.isEmpty ? "?" : String(trimmed.prefix(1)).uppercased()
    }
}

@Model
final class AppSettings {
    var unitsRaw: String = Units.kg.rawValue
    var darkMode: Bool = false
    var restTimerAuto: Bool = false
    var restSeconds: Int = 90

    init() {}

    var units: Units {
        get { Units(rawValue: unitsRaw) ?? .kg }
        set { unitsRaw = newValue.rawValue }
    }
}

//
//  ProgressAggregator.swift
//  Replog
//
//  Turns an exercise's history into the numbers the Progress screens show:
//  best & current estimated 1RM, trend %, and a sparkline series.
//

import Foundation

struct ExerciseProgress: Equatable, Sendable {
    var exId: String
    var bestE1rm: Int
    var currentE1rm: Int
    /// Percent change of the latest session's e1RM vs the prior session, or nil.
    var trendPercent: Double?
    /// e1RM over time (oldest -> newest) for the chart/sparkline.
    var series: [Int]
    var sessionCount: Int

    var hasData: Bool { sessionCount > 0 }
    var trend: Trend {
        guard let trendPercent else { return .none }
        if trendPercent > 0 { return .up }
        if trendPercent < 0 { return .down }
        return .flat
    }
}

enum ProgressAggregator {
    /// Summarizes a single exercise's history (any order; sorted internally by date).
    static func summarize(exId: String, history: [HistoryEntry]) -> ExerciseProgress {
        let sorted = history.sorted { $0.date < $1.date }
        let series = sorted.map(\.e1rm)
        let best = series.max() ?? 0
        let current = series.last ?? 0
        let previous = series.count >= 2 ? series[series.count - 2] : nil
        let trend = TrendCalculator.percentChange(current: Double(current),
                                                  previous: previous.map(Double.init))
        return ExerciseProgress(
            exId: exId,
            bestE1rm: best,
            currentE1rm: current,
            trendPercent: trend,
            series: series,
            sessionCount: sorted.count
        )
    }
}

//
//  MainTabView.swift
//  Replog
//
//  The five-tab shell: Today · Plans · Library · Progress · Profile.
//  Each tab owns a NavigationStack for drill-downs.
//

import SwiftUI

struct MainTabView: View {
    @State private var selection: Tab = .today

    enum Tab: Hashable { case today, plans, library, progress, profile }

    init() {
        #if DEBUG
        if let tab = DebugSeed.initialTab { _selection = State(initialValue: tab) }
        #endif
    }

    var body: some View {
        TabView(selection: $selection) {
            TodayView()
                .tabItem { Label("Today", systemImage: "house") }.tag(Tab.today)
            PlansListView()
                .tabItem { Label("Plans", systemImage: "square.stack.3d.up") }.tag(Tab.plans)
            LibraryView()
                .tabItem { Label("Library", systemImage: "books.vertical") }.tag(Tab.library)
            ProgressDashboardView()
                .tabItem { Label("Progress", systemImage: "chart.line.uptrend.xyaxis") }.tag(Tab.progress)
            ProfileView()
                .tabItem { Label("Profile", systemImage: "person") }.tag(Tab.profile)
        }
        .tint(.accent)
    }
}

//
//  Scheduling.swift
//  Replog
//
//  Weekday assignment for adding workouts to a plan. New days prefer the classic
//  Mon/Wed/Fri cadence, then fill remaining days; taken days are never reused.
//

import Foundation

enum WeekdayPlanner {
    /// Preference order when auto-assigning a new workout's day.
    static let preferred: [Weekday] = [.mon, .wed, .fri, .sun, .tue, .thu, .sat]

    /// The first free weekday not already used, in preference order. Nil if all 7 taken.
    static func firstFreeDay(excluding used: Set<Weekday>) -> Weekday? {
        preferred.first { !used.contains($0) }
    }

    /// Whether a day can be chosen given the days used by *other* workouts.
    static func isAvailable(_ day: Weekday, usedByOthers used: Set<Weekday>) -> Bool {
        !used.contains(day)
    }
}

