//
//  WeeklyReport.swift
//  Replog
//
//  The coach's weekly review: a pure composer that digests one calendar week of
//  training (adherence, volume, PRs, stall notes, bodyweight trend) into the markdown
//  the user reads, plus a publisher that stores it as a `CoachingLog(.weeklyReport)`
//  exactly once per week. Rendering reuses `CoachReportView` (the AI plan reports).
//
//  Weeks follow the Today week strip: Sunday-started, via `StreakEngine.startOfWeek`.
//  A report covers the most recently *completed* week and is only published when that
//  week had at least one training day — an empty week produces no report.
//

import Foundation
import SwiftData

/// One composed weekly review, ready to store and render.
struct WeeklyReport: Sendable {
    /// Start of the reviewed week (Sunday, start of day).
    var weekStart: Date
    /// Reader-facing title, e.g. "Week of Jun 22–28".
    var title: String
    /// The full rendered report (CoachReportView's markdown dialect).
    var markdown: String
    /// Training days completed in the week.
    var workoutsDone: Int
    /// Distinct scheduled weekdays (0 when no plan has a schedule).
    var workoutsScheduled: Int
    /// Lifts that set a new all-time e1RM best during the week.
    var prCount: Int
    /// Total tonnage lifted in the week, in kg.
    var totalVolumeKg: Double
    /// Total working sets logged in the week.
    var totalSets: Int
}

enum WeeklyReportComposer {

    /// Payload metric key identifying which week a stored report covers (dedup key).
    static let weekStartMetric = "weekStart"
    /// Payload metric keys surfaced in the Profile list row.
    static let workoutsMetric = "workoutsDone"
    static let scheduledMetric = "workoutsScheduled"
    static let prMetric = "prCount"
    /// At most this many PR / coach-note bullets are rendered.
    static let maxBullets = 3

    /// The start of the most recently completed week — the one a report published
    /// "now" covers.
    static func previousWeekStart(now: Date = Date(), calendar: Calendar = .current) -> Date? {
        guard let thisWeek = StreakEngine.startOfWeek(for: now, calendar: calendar) else { return nil }
        return calendar.date(byAdding: .day, value: -7, to: thisWeek)
    }

    /// Composes the review for the week starting `weekStart`. Pure: everything is
    /// passed in. Returns nil when the week had no completed training days.
    ///
    /// - Parameters:
    ///   - history: the user's FULL history (pre-week entries are the PR baseline).
    ///   - nameFor: resolves a catalog exId to a display name.
    @MainActor
    static func compose(
        weekStart: Date,
        history: [HistoryEntry],
        doneDates: [Date],
        scheduledDays: Set<Weekday>,
        coachingLogs: [CoachingLog],
        bodyweightEntries: [BodyweightEntry],
        firstName: String,
        goal: Goal,
        units: Units,
        nameFor: (String) -> String = ReportComposer.prettyName,
        calendar: Calendar = .current
    ) -> WeeklyReport? {
        guard let weekEnd = calendar.date(byAdding: .day, value: 7, to: weekStart) else { return nil }
        let inWeek = { (date: Date) in date >= weekStart && date < weekEnd }

        // A "workout" is a completed training day (the WorkoutHistory reconstruction):
        // the union of marked-done days and days with logged sets.
        let weekDays = WorkoutHistory.completedDays(doneDates: doneDates, history: history,
                                                    calendar: calendar)
            .filter { inWeek($0.day) }
        guard !weekDays.isEmpty else { return nil }

        let weekEntries = history.filter { inWeek($0.date) }
        let totalSets = weekEntries.reduce(0) { $0 + max(1, $1.sets.count) }
        let totalVolumeKg = weekEntries.reduce(0.0) { sum, entry in
            let sets = entry.sets
            return sum + (sets.isEmpty ? entry.topW * Double(entry.topR)
                                       : sets.reduce(0) { $0 + $1.w * Double($1.r) })
        }

        let prs = personalRecords(weekEntries: weekEntries,
                                  priorHistory: history.filter { $0.date < weekStart })
        let title = "Week of \(rangeText(weekStart: weekStart, calendar: calendar))"

        var md = "# \(title)\n"
        md += "\(firstName.isEmpty ? "Here's" : "\(firstName), here's") your week in review.\n\n"

        // Training
        md += "## Training\n"
        let doneText = "**\(weekDays.count)** workout\(weekDays.count == 1 ? "" : "s")"
        if scheduledDays.isEmpty {
            md += "- \(doneText) completed.\n"
        } else if weekDays.count >= scheduledDays.count {
            md += "- \(doneText) of \(scheduledDays.count) scheduled — a perfect week.\n"
        } else {
            md += "- \(doneText) of \(scheduledDays.count) scheduled.\n"
        }
        if totalSets > 0 {
            md += "- **\(totalSets)** working set\(totalSets == 1 ? "" : "s") logged.\n"
            md += "- **\(volumeText(kg: totalVolumeKg, units: units))** total volume lifted.\n"
        }
        md += "\n"

        // Highlights
        md += "## Highlights\n"
        if prs.isEmpty {
            md += "No new records this week — consistency first, the PRs follow.\n"
        } else {
            for pr in prs.prefix(maxBullets) {
                md += "- **New PR:** \(nameFor(pr.exId)) — est. 1RM \(pr.newBest) (up from \(pr.priorBest)).\n"
            }
        }
        if let riser = topProgressingLift(weekEntries: weekEntries, history: history,
                                          before: weekEnd, excluding: Set(prs.map(\.exId))) {
            md += "- **Trending up:** \(nameFor(riser.exId)), \(String(format: "%+.1f", riser.percent))% this week.\n"
        }
        md += "\n"

        // Coach's notes — the stall detector's memory of the week, else a default cue.
        md += "## Coach's notes\n"
        let notes = coachingLogs
            .filter { inWeek($0.date) && ($0.kind == .plateau || $0.kind == .deload) }
            .sorted { $0.date > $1.date }
        if notes.isEmpty {
            md += "\(defaultNote(done: weekDays.count, scheduled: scheduledDays.count, goal: goal))\n"
        } else {
            for note in notes.prefix(maxBullets) {
                md += "- \(note.summary)\n"
            }
        }
        md += "\n"

        // Bodyweight — the series as it stood at week's end.
        if let snapshot = BodyweightTracker.snapshot(
            entries: bodyweightEntries.filter { $0.date < weekEnd }) {
            md += "## Bodyweight\n"
            var line = "- **\(Formulas.formatBodyweight(kg: snapshot.currentKg, units: units))**"
            if let rate = snapshot.weeklyRateKg, snapshot.direction != .flat, snapshot.direction != .none {
                let formatted = Formulas.formatBodyweight(kg: abs(rate), units: units)
                line += " — trending \(snapshot.direction == .up ? "up" : "down") \(formatted)/week."
                md += line + "\n"
                switch BodyweightTracker.isFavorable(snapshot.direction, for: goal) {
                case true?: md += "That's the right direction for your goal — keep it up.\n"
                case false?: md += "That's moving against your goal — worth a look at recovery and nutrition.\n"
                case nil: break
                }
            } else {
                line += " — holding steady."
                md += line + "\n"
            }
            md += "\n"
        }

        md += "> \(encouragement(firstName: firstName, done: weekDays.count, prCount: prs.count))\n"

        return WeeklyReport(
            weekStart: weekStart,
            title: title,
            markdown: md,
            workoutsDone: weekDays.count,
            workoutsScheduled: scheduledDays.count,
            prCount: prs.count,
            totalVolumeKg: totalVolumeKg,
            totalSets: totalSets
        )
    }

    // MARK: - Publishing

    /// Composes and stores the previous week's report as a `CoachingLog(.weeklyReport)`,
    /// exactly once per week (dedup on the `weekStart` payload metric). Skips weeks with
    /// no training. Inserts without saving — the caller owns the save, as elsewhere.
    @MainActor
    @discardableResult
    static func publishIfDue(
        context: ModelContext,
        nameFor: (String) -> String = ReportComposer.prettyName,
        now: Date = Date(),
        calendar: Calendar = .current
    ) -> CoachingLog? {
        guard let weekStart = previousWeekStart(now: now, calendar: calendar) else { return nil }
        let key = weekStart.timeIntervalSinceReferenceDate
        let published = context.coachingLogs(kind: .weeklyReport)
        guard !published.contains(where: { $0.payload[metric: weekStartMetric] == key }) else {
            return nil
        }

        let profile = context.userProfile()
        let history = (try? context.fetch(FetchDescriptor<HistoryEntry>())) ?? []
        guard let report = compose(
            weekStart: weekStart,
            history: history,
            doneDates: profile.doneDates,
            scheduledDays: StreakEngine.scheduledDays(in: context.allPlans()),
            coachingLogs: context.coachingLogs(),
            bodyweightEntries: context.bodyweightEntries(),
            firstName: profile.firstName == "there" ? "" : profile.firstName,
            goal: profile.goal,
            units: context.appSettings().units,
            nameFor: nameFor,
            calendar: calendar
        ) else { return nil }

        return context.recordCoaching(
            .weeklyReport,
            summary: report.title,
            date: now,
            payload: CoachingPayload(metrics: [
                weekStartMetric: key,
                workoutsMetric: Double(report.workoutsDone),
                scheduledMetric: Double(report.workoutsScheduled),
                prMetric: Double(report.prCount)
            ]),
            body: report.markdown
        )
    }

    // MARK: - Internals

    struct PersonalRecord: Equatable, Sendable {
        var exId: String
        var newBest: Int
        var priorBest: Int
    }

    /// Lifts whose best in-week e1RM beats their all-time pre-week best. A lift's very
    /// first entries don't count — a "record" needs a baseline to beat.
    @MainActor
    static func personalRecords(weekEntries: [HistoryEntry],
                                priorHistory: [HistoryEntry]) -> [PersonalRecord] {
        let priorBest = Dictionary(grouping: priorHistory, by: \.exId)
            .mapValues { $0.map(\.e1rm).max() ?? 0 }
        let weekBest = Dictionary(grouping: weekEntries, by: \.exId)
            .mapValues { $0.map(\.e1rm).max() ?? 0 }
        return weekBest.compactMap { exId, best in
            guard let prior = priorBest[exId], best > prior else { return nil }
            return PersonalRecord(exId: exId, newBest: best, priorBest: prior)
        }
        .sorted { $0.newBest > $1.newBest }
    }

    /// The week's strongest positive mover (latest-vs-previous e1RM %) among lifts
    /// trained this week, excluding those already celebrated as PRs.
    @MainActor
    private static func topProgressingLift(
        weekEntries: [HistoryEntry],
        history: [HistoryEntry],
        before weekEnd: Date,
        excluding: Set<String>
    ) -> (exId: String, percent: Double)? {
        Set(weekEntries.map(\.exId)).subtracting(excluding)
            .compactMap { exId -> (String, Double)? in
                let trail = history.filter { $0.exId == exId && $0.date < weekEnd }
                guard let percent = ProgressAggregator.summarize(exId: exId, history: trail).trendPercent,
                      percent > 0 else { return nil }
                return (exId, percent)
            }
            .max { $0.1 < $1.1 }
            .map { (exId: $0.0, percent: $0.1) }
    }

    private static func defaultNote(done: Int, scheduled: Int, goal: Goal) -> String {
        if scheduled > 0 && done < scheduled {
            return "You missed \(scheduled - done) scheduled session\(scheduled - done == 1 ? "" : "s") — " +
                   "for \(goal.shortName.lowercased()), showing up is the single biggest lever. " +
                   "Protect those training days next week."
        }
        return "No stalls detected and every session done — recovery and consistency are " +
               "on point. Keep nudging the loads and reps up."
    }

    private static func encouragement(firstName: String, done: Int, prCount: Int) -> String {
        let name = firstName.isEmpty ? "" : "\(firstName), "
        if prCount > 0 {
            return "\(name)\(prCount == 1 ? "a new record" : "\(prCount) new records") in one week — " +
                   "that's progressive overload working. See you under the bar."
        }
        return "\(name)\(done) session\(done == 1 ? "" : "s") banked. Progress compounds — " +
               "next week we go again."
    }

    /// "Jun 22–28" or "Jun 29 – Jul 5" across a month boundary.
    private static func rangeText(weekStart: Date, calendar: Calendar) -> String {
        let lastDay = calendar.date(byAdding: .day, value: 6, to: weekStart) ?? weekStart
        let start = weekStart.formatted(.dateTime.month(.abbreviated).day())
        let sameMonth = calendar.isDate(weekStart, equalTo: lastDay, toGranularity: .month)
        let end = sameMonth ? lastDay.formatted(.dateTime.day())
                            : lastDay.formatted(.dateTime.month(.abbreviated).day())
        return sameMonth ? "\(start)–\(end)" : "\(start) – \(end)"
    }
}

