//
//  WeeklyReportTests.swift
//  ReplogTests
//
//  The weekly report (D1): the pure composer (adherence, volume, PRs, stall notes,
//  bodyweight trend, empty-week nil) against fixed fixtures, and the publisher's
//  once-per-week CoachingLog write.
//

import Testing
import Foundation
import SwiftData
@testable import Replog

@MainActor
struct WeeklyReportTests {

    private let cal = Calendar.current
    /// A fixed "now"; all fixture dates are laid out relative to it.
    private let now = Date(timeIntervalSinceReferenceDate: 761_000_000)

    private var weekStart: Date { WeeklyReportComposer.previousWeekStart(now: now, calendar: cal)! }

    private func day(_ offset: Int) -> Date {
        cal.date(byAdding: .day, value: offset, to: weekStart)!
    }

    private func entry(_ exId: String, day offset: Int, topW: Double, topR: Int,
                       sets: [RecordedSet]? = nil) -> HistoryEntry {
        HistoryEntry(exId: exId, date: day(offset), topW: topW, topR: topR,
                     e1rm: Formulas.e1rmRounded(kg: topW, reps: topR),
                     sets: sets ?? [RecordedSet(w: topW, r: topR)])
    }

    private func compose(
        history: [HistoryEntry] = [],
        doneDates: [Date] = [],
        scheduledDays: Set<Weekday> = [],
        coachingLogs: [CoachingLog] = [],
        bodyweightEntries: [BodyweightEntry] = [],
        firstName: String = "Alex",
        goal: Goal = .buildMuscle,
        units: Units = .kg
    ) -> WeeklyReport? {
        WeeklyReportComposer.compose(
            weekStart: weekStart, history: history, doneDates: doneDates,
            scheduledDays: scheduledDays, coachingLogs: coachingLogs,
            bodyweightEntries: bodyweightEntries, firstName: firstName,
            goal: goal, units: units, calendar: cal
        )
    }

    // MARK: - Week boundaries

    @Test func previousWeekStartIsTheSundayBeforeTheCurrentWeek() throws {
        let start = try #require(WeeklyReportComposer.previousWeekStart(now: now, calendar: cal))
        #expect(start == cal.startOfDay(for: start))
        #expect(cal.component(.weekday, from: start) == 1) // Sunday, matching the week strip
        let daysBack = cal.dateComponents([.day], from: start, to: cal.startOfDay(for: now)).day!
        #expect((7...13).contains(daysBack))
    }

    @Test func titleNamesTheWeek() throws {
        let report = try #require(compose(history: [entry("Barbell_Squat", day: 1, topW: 100, topR: 5)]))
        #expect(report.title.hasPrefix("Week of "))
        #expect(report.markdown.contains("# \(report.title)"))
    }

    // MARK: - Empty / activity gate

    @Test func emptyWeekComposesNothing() {
        // History and completions exist, but none inside the reviewed week.
        let outside = [entry("Barbell_Squat", day: -3, topW: 100, topR: 5),
                       entry("Barbell_Squat", day: 9, topW: 102.5, topR: 5)]
        #expect(compose(history: outside, doneDates: [day(-1), day(8)]) == nil)
    }

    // MARK: - Training section

    @Test func workoutDaysAreTheUnionOfDoneDatesAndHistoryDays() throws {
        // Two history days, one of them also marked done, plus one done-only day → 3.
        let history = [entry("Barbell_Squat", day: 0, topW: 100, topR: 5),
                       entry("Barbell_Bench_Press", day: 2, topW: 80, topR: 8)]
        let report = try #require(compose(history: history, doneDates: [day(0), day(4)]))
        #expect(report.workoutsDone == 3)
    }

    @Test func perfectWeekIsCalledOut() throws {
        let history = [entry("Barbell_Squat", day: 0, topW: 100, topR: 5),
                       entry("Barbell_Bench_Press", day: 2, topW: 80, topR: 8)]
        let report = try #require(compose(history: history, scheduledDays: [.mon, .wed]))
        #expect(report.markdown.contains("a perfect week"))
    }

    @Test func missedSessionsDriveTheDefaultCoachNote() throws {
        let history = [entry("Barbell_Squat", day: 0, topW: 100, topR: 5)]
        let report = try #require(compose(history: history, scheduledDays: [.mon, .wed, .fri]))
        #expect(report.markdown.contains("missed 2 scheduled sessions"))
    }

    @Test func setAndVolumeTotalsSumTheWeeksSets() throws {
        let sets = [RecordedSet(w: 100, r: 5), RecordedSet(w: 90, r: 8)]
        let report = try #require(compose(history: [
            entry("Barbell_Squat", day: 1, topW: 100, topR: 5, sets: sets)
        ]))
        #expect(report.totalSets == 2)
        #expect(report.totalVolumeKg == 100 * 5 + 90 * 8)
        #expect(report.markdown.contains(WeeklyReportComposer.volumeText(kg: 1220, units: .kg)))
    }

    @Test func entryWithoutStoredSetsFallsBackToItsTopSet() throws {
        let report = try #require(compose(history: [
            entry("Barbell_Squat", day: 1, topW: 100, topR: 5, sets: [])
        ]))
        #expect(report.totalSets == 1)
        #expect(report.totalVolumeKg == 500)
    }

    // MARK: - PRs

    @Test func beatingThePreWeekBestIsAPR() throws {
        let history = [entry("Barbell_Squat", day: -10, topW: 100, topR: 5),
                       entry("Barbell_Squat", day: 2, topW: 105, topR: 5)]
        let report = try #require(compose(history: history))
        #expect(report.prCount == 1)
        #expect(report.markdown.contains("New PR:"))
        #expect(report.markdown.contains("Barbell Squat"))
    }

    @Test func aLiftsFirstEverSessionIsNotAPR() throws {
        let report = try #require(compose(history: [
            entry("Barbell_Squat", day: 2, topW: 105, topR: 5)
        ]))
        #expect(report.prCount == 0)
        #expect(report.markdown.contains("No new records this week"))
    }

    @Test func twoImprovementsInOneWeekCountOnce() {
        let prior = [entry("Barbell_Squat", day: -10, topW: 100, topR: 5)]
        let week = [entry("Barbell_Squat", day: 1, topW: 102.5, topR: 5),
                    entry("Barbell_Squat", day: 4, topW: 105, topR: 5)]
        let prs = WeeklyReportComposer.personalRecords(weekEntries: week, priorHistory: prior)
        #expect(prs.count == 1)
        #expect(prs[0].newBest == Formulas.e1rmRounded(kg: 105, reps: 5))
        #expect(prs[0].priorBest == Formulas.e1rmRounded(kg: 100, reps: 5))
    }

    @Test func trendingUpNamesAnImprovingNonPRLift() throws {
        // Bench: all-time best pre-week, dip, then an in-week recovery — improving
        // session-over-session but below its old best, so a riser rather than a PR.
        let history = [entry("Barbell_Bench_Press", day: -14, topW: 100, topR: 5),
                       entry("Barbell_Bench_Press", day: -7, topW: 90, topR: 5),
                       entry("Barbell_Bench_Press", day: 3, topW: 95, topR: 5)]
        let report = try #require(compose(history: history))
        #expect(report.prCount == 0)
        #expect(report.markdown.contains("Trending up:"))
        #expect(report.markdown.contains("Barbell Bench Press"))
    }

    // MARK: - Coach's notes

    @Test func stallLogsInsideTheWeekBecomeCoachNotes() throws {
        let inWeek = CoachingLog(kind: .deload, summary: "Bench stalled — try 55kg", date: day(3))
        let wrongKind = CoachingLog(kind: .note, summary: "not a stall", date: day(3))
        let outside = CoachingLog(kind: .plateau, summary: "old stall", date: day(-2))
        let report = try #require(compose(
            history: [entry("Barbell_Squat", day: 1, topW: 100, topR: 5)],
            coachingLogs: [inWeek, wrongKind, outside]
        ))
        #expect(report.markdown.contains("Bench stalled — try 55kg"))
        #expect(!report.markdown.contains("not a stall"))
        #expect(!report.markdown.contains("old stall"))
    }

    // MARK: - Bodyweight section

    @Test func bodyweightTrendRendersWithGoalCommentary() throws {
        // A clear downward series before week's end; goal is buildMuscle → unfavorable.
        let entries = stride(from: 0, to: 5, by: 1).map { i in
            BodyweightEntry(weightKg: 80 - Double(i) * 0.6, date: day(-21 + i * 7))
        }
        let report = try #require(compose(
            history: [entry("Barbell_Squat", day: 1, topW: 100, topR: 5)],
            bodyweightEntries: entries
        ))
        #expect(report.markdown.contains("## Bodyweight"))
        #expect(report.markdown.contains("trending down"))
        #expect(report.markdown.contains("moving against your goal"))
    }

    @Test func bodyweightSectionOmittedWithoutEntries() throws {
        let report = try #require(compose(history: [entry("Barbell_Squat", day: 1, topW: 100, topR: 5)]))
        #expect(!report.markdown.contains("## Bodyweight"))
    }

    @Test func bodyweightEntriesAfterTheWeekAreIgnored() throws {
        // Only one entry lands before week's end → no rate, "holding steady".
        let entries = [BodyweightEntry(weightKg: 80, date: day(2)),
                       BodyweightEntry(weightKg: 70, date: day(9))]
        let report = try #require(compose(
            history: [entry("Barbell_Squat", day: 1, topW: 100, topR: 5)],
            bodyweightEntries: entries
        ))
        #expect(report.markdown.contains("holding steady"))
        #expect(report.markdown.contains(Formulas.formatBodyweight(kg: 80, units: .kg)))
    }

    // MARK: - Units

    @Test func volumeTextConvertsRawWithoutPlateRounding() {
        #expect(WeeklyReportComposer.volumeText(kg: 100, units: .kg) == "100kg")
        #expect(WeeklyReportComposer.volumeText(kg: 100, units: .lb) == "220lb")
    }

    // MARK: - Publisher

    private func makeContext() -> ModelContext {
        ModelContext(ReplogSchema.inMemoryContainer())
    }

    @Test func publishStoresLastWeeksReportExactlyOnce() throws {
        let ctx = makeContext()
        ctx.userProfile().name = "Alex"
        ctx.insert(entry("Barbell_Squat", day: 2, topW: 100, topR: 5))
        try ctx.save()

        let log = try #require(WeeklyReportComposer.publishIfDue(context: ctx, now: now, calendar: cal))
        try ctx.save()
        #expect(log.kind == .weeklyReport)
        #expect(log.summary.hasPrefix("Week of "))
        #expect(log.bodyMarkdown?.contains("## Training") == true)
        #expect(log.payload[metric: WeeklyReportComposer.weekStartMetric]
                == weekStart.timeIntervalSinceReferenceDate)
        #expect(log.payload[metric: WeeklyReportComposer.workoutsMetric] == 1)

        // Same week again → no duplicate.
        #expect(WeeklyReportComposer.publishIfDue(context: ctx, now: now, calendar: cal) == nil)
        #expect(ctx.coachingLogs(kind: .weeklyReport).count == 1)
    }

    @Test func publishSkipsAWeekWithNoTraining() throws {
        let ctx = makeContext()
        _ = ctx.userProfile()
        #expect(WeeklyReportComposer.publishIfDue(context: ctx, now: now, calendar: cal) == nil)
        #expect(ctx.coachingLogs(kind: .weeklyReport).isEmpty)
    }

    @Test func publishedMarkdownSurvivesSaveAndFetch() throws {
        let ctx = makeContext()
        _ = ctx.userProfile()
        ctx.insert(entry("Barbell_Squat", day: 2, topW: 100, topR: 5))
        _ = WeeklyReportComposer.publishIfDue(context: ctx, now: now, calendar: cal)
        try ctx.save()

        let fetched = try #require(ctx.coachingLogs(kind: .weeklyReport).first)
        #expect(fetched.bodyMarkdown?.hasPrefix("# Week of ") == true)
    }
}

