    @Query private var plans: [Plan]
    @Query private var history: [HistoryEntry]
    // Literal raw value: #Predicate can't evaluate CoachingKind.weeklyReport.rawValue.
    @Query(filter: #Predicate<CoachingLog> { $0.kindRaw == "weeklyReport" },
           sort: \CoachingLog.date, order: .reverse)
    private var weeklyReports: [CoachingLog]
    @State private var showResetConfirm = false
    @State private var selectedStat: StatKind?
    @State private var showSeededWeeklyReport = false

